public static METAssetReportController construct()
{
    return new METAssetReportController();
}

public static void main(Args _args)
{
    SrsReportRunController formLetterController = METAssetReportController::construct();
    METAssetReportController controller = formLetterController;
    controller.parmReportName(ssrsReportStr(METAssetBalances, Report));
    controller.parmArgs(_args);
    controller.startOperation();
}
